const ROOMS = [['cBed', 'ห้องนอน', 3, 8], ['cBath', 'ห้องน้ำ', 2, 8], ['cWork', 'ห้องทำงาน', 0, 3], ['cPray', 'ห้องพระ', 0, 2], ['cStore', 'ห้องเก็บของ', 0, 3], ['cMaid', 'ห้องแม่บ้าน', 0, 2], ['cMulti', 'ห้องอเนกประสงค์/ห้องดูหนัง', 0, 2], ['cCar', 'ที่จอดรถ (คัน)', 1, 4]];
