/* รูปตัวอย่างที่ลูกค้าแนบ — ย่อในเครื่องให้ไม่เกิน 1280 จุดภาพ แล้วส่งให้ระบบออกแบบดู (ไม่อัปโหลดเก็บ) */
let refImgs = [];
